<script setup lang="ts">
import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { useI18n } from 'vue-i18n'; import { workspace } from '../demo/workspace'; import type { EntityCollection } from '../domain'; import { pageLocation, entityLocation } from '../app/router'; import { pageRoutes, type PageName } from '../app/routes'; import PageHeader from './PageHeader.vue'; import ControllerInfo from './ControllerInfo.vue'; import DraftSandbox from './DraftSandbox.vue'
const props = defineProps<{ feature: string; page: string }>(); const route = useRoute(); const { t } = useI18n()
const collection = computed(() => route.meta.collection as EntityCollection | undefined)
const entity = computed(() => collection.value ? workspace[collection.value].find(x => x.id === route.params[String(route.meta.idParam)]) : undefined)
const missing = computed(() => !!collection.value && !entity.value)
const parent = computed(() => (route.meta.parent ?? 'overview') as PageName)
const related = computed(() => pageRoutes.filter(r => !r.path.includes(':') && r.meta.parent === route.meta.parent && r.name !== route.name))
const entities = computed(() => { const key = ({ nodes: 'nodes', routes: 'routes', subscriptions: 'subscriptions', 'rule-profiles': 'profiles', activity: 'releases' } as const)[String(route.name) as 'nodes']; return key ? workspace[key] : [] })
const kind = computed(() => ({ nodes: 'node', routes: 'route', subscriptions: 'subscription', 'rule-profiles': 'profile', activity: 'release' } as const)[String(route.name) as 'nodes'])
</script><template><PageHeader :title="missing ? t('common.notFound') : t(`features.${props.feature}.${props.page}.title`)" :description="missing ? t('common.missing') : t(`features.${props.feature}.${props.page}.goal`)" /><section class="panel"><p class="eyebrow">{{ t('common.pending') }}</p><h2 v-if="entity">{{ entity.name }}</h2><p>{{ t('app.boundary') }}</p><RouterLink :to="pageLocation(parent)">{{ t('common.back') }}</RouterLink><nav class="link-list" :aria-label="t('common.related')"><RouterLink v-for="r in related" :key="r.name" :to="pageLocation(r.name)">{{ t(r.meta.titleKey) }}</RouterLink><RouterLink v-for="item in entities" :key="item.id" :to="entityLocation(kind, item.id)">{{ item.name }}</RouterLink><RouterLink v-if="route.name === 'node-detail' && entity" :to="pageLocation('routes', {}, { nodeId: entity.id })">{{ t('nav.routes') }}</RouterLink><RouterLink v-if="route.name === 'route-detail' && entity" :to="pageLocation('route-edit', { routeId: entity.id })">{{ t('features.route-editor.RouteEditorPage.title') }}</RouterLink><RouterLink v-if="route.name === 'subscription-detail' && entity" :to="pageLocation('subscription-edit', { subscriptionId: entity.id })">{{ t('features.subscriptions.SubscriptionEditorPage.title') }}</RouterLink></nav></section><template v-if="route.name === 'settings'"><ControllerInfo /><DraftSandbox /></template></template>
